def validate_survey_777(payload):
    """Validate a survey payload: 'count' must be in [-50, 50]."""
    if not isinstance(payload, dict):
        return False
    count = payload.get("count")
    if not isinstance(count, (int, float)):
        return False
    return -50 <= count <= 50

