def trend_report(values_by_group):
    """Smooth each group's series, then average the smoothed values."""
    smoothed_groups = {}

    for region, values in values_by_group.items():
        if not values:
            smoothed_groups[region] = []
            continue

        # Sort values by index (assuming input is a list of values for the region)
        # If values_by_group is a dict mapping region -> list of values
        sorted_values = sorted(values)

        # Simple moving average smoothing (window size 3)
        smoothed = []
        window = 3
        for i in range(len(sorted_values)):
            start = max(0, i - window + 1)
            end = min(len(sorted_values), i + 1)
            window_values = sorted_values[start:end]
            smoothed.append(sum(window_values) / len(window_values))

